using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Linq;
[InitializeOnLoad] public static class HunterTorchCorrection {
 const string E="Evidence/hunter-torch-correction-20261030/";
 static HunterTorchCorrection(){EditorApplication.delayCall+=AttachBindingTest;}
 static void AttachBindingTest(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists(E+"binding-attached.txt"))return;var p=Object.FindObjectOfType<HunterTorchPose>();if(!p)return;if(!p.GetComponent<HunterTorchCorrectionProbe>())p.gameObject.AddComponent<HunterTorchCorrectionProbe>();EditorSceneManager.SaveScene(p.gameObject.scene);File.WriteAllText(E+"binding-attached.txt","Rigid palm binding test attached.");}
 static void Fix(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists(E+"fixed.txt"))return;Directory.CreateDirectory(E);EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueSettlement_HunterTorch.unity");var p=Object.FindObjectOfType<HunterTorchPose>();var a=p.bridge.animator;var torch=a.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Hunter Left Torch");
 var mesh=torch.GetComponentInChildren<MeshFilter>().transform;mesh.localRotation=Quaternion.identity;mesh.localPosition=new Vector3(0,.15f,0);
 foreach(var ps in torch.GetComponentsInChildren<ParticleSystem>()){ps.transform.localPosition=new Vector3(0,ps.name=="fx_smoke"?.79f:.70f,0);if(ps.name=="fx_fire")ps.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Viking Village/Materials/Effects/mat_fx_fire_01.mat");}
 var fire=torch.GetComponentsInChildren<ParticleSystem>().First(x=>x.name=="fx_fire").transform;var light=p.GetComponentsInChildren<Light>(true).First(x=>x.name=="Carried lantern");light.transform.SetParent(fire,true);light.transform.localPosition=Vector3.zero;
 File.WriteAllText(E+"fixed.txt","Original ground-fire material assigned directly (including HDR emission). Torch mesh tilt removed, grip y=-.15 mesh-space; palm centered at 68% wrist-to-knuckles. Existing main light reparented to fx_fire, intensity="+light.intensity+" range="+light.range+" components="+string.Join(",",light.GetComponents<Component>().Where(x=>x).Select(x=>x.GetType().Name))+"\n");
 PrefabUtility.SaveAsPrefabAsset(p.gameObject,"Assets/Demo/Characters/Hunter/Torch/Hunter_TorchPlayer.prefab");EditorSceneManager.SaveScene(p.gameObject.scene);AssetDatabase.SaveAssets();if(!p.GetComponent<HunterTorchCorrectionProbe>())p.gameObject.AddComponent<HunterTorchCorrectionProbe>();EditorSceneManager.SaveScene(p.gameObject.scene);
 }
 static void FinishWhenTested(){if(!File.Exists(E+"saved.txt")&&File.Exists(E+"playmode.txt")&&File.ReadAllText(E+"playmode.txt").Contains("end state="))Finish();}
 [MenuItem("Vampire Demo/Hunter/Finish Torch Correction")]static void Finish(){if(EditorApplication.isPlaying)return;var p=Object.FindObjectOfType<HunterTorchPose>();if(!p)return;var hand=p.bridge.animator.GetBoneTransform(HumanBodyBones.LeftHand);var grip=hand.Find("Left Palm Torch Grip");if(!grip){var data=JsonUtility.FromJson<HunterTorchCorrectionProbe.GripData>(File.ReadAllText(E+"grip.json"));grip=new GameObject("Left Palm Torch Grip").transform;grip.SetParent(hand,false);grip.localPosition=data.position;grip.localRotation=data.rotation;var torch=p.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Hunter Left Torch");torch.SetParent(grip,true);torch.localPosition=Vector3.zero;torch.localRotation=Quaternion.identity;}var old=p.GetComponentsInChildren<Light>(true).First(l=>l.name=="Carried lantern").GetComponent<Renderer>();if(old)old.enabled=false;foreach(var probe in p.GetComponents<HunterTorchCorrectionProbe>())Object.DestroyImmediate(probe);PrefabUtility.SaveAsPrefabAsset(p.gameObject,"Assets/Demo/Characters/Hunter/Torch/Hunter_TorchPlayer.prefab");var path=p.gameObject.scene.path;EditorSceneManager.SaveScene(p.gameObject.scene);EditorSceneManager.OpenScene(path);object[] counts={0,0,0};var t=typeof(Editor).Assembly.GetType("UnityEditor.LogEntries");t.GetMethod("GetCountsByType",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic).Invoke(null,counts);File.WriteAllText(E+"saved.txt","Saved and reopened "+path+"; test probe removed. errors="+counts[0]+" warnings="+counts[1]);}
}